import time

from playwright.sync_api import Page, expect

# Generated by an AI assistant from the prompt: "Write Playwright tests for the search page".
# The assistant saw neither the page nor the requirements. Review and fix.


def test_search_works(page: Page):
    page.goto("/playground/search")
    page.locator("#search-box").fill("MOUSE")
    time.sleep(3)
    count = page.locator(".product-card").count()
    assert count > 0


def test_in_stock_filter_works(page: Page):
    page.goto("/playground/search")
    page.get_by_label("In stock only").check()
    page.wait_for_timeout(2000)
    expect(page.get_by_test_id("result-count")).to_have_text("12 products found")


def test_sorting_by_price_works(page: Page):
    page.goto("/playground/search")
    page.get_by_label("Sort by").select_option("price-desc")
    first = page.get_by_test_id("product-name").first.text_content()
    assert first
